UPDATE dag_node_instance
SET lease_expire_time = #{leaseExpireTime}
WHERE id = #{id}
  AND lease_owner = #{leaseOwner}
  AND status = 'RUNNING'
  AND deleted = 0

UPDATE dag_instance
SET trace_code = #{traceCode}
WHERE instance_code = #{instanceCode}
  AND (trace_code IS NULL OR trace_code = '')
  AND deleted = 0
